{"node_id": "LVMC_11_52_136", "law_refs": ["LVMC-11-52-136"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "No person shall park", "role": "obligation"}, {"id": "s2", "text": "a vehicle", "role": "subject"}, {"id": "s3", "text": "in an access aisle.", "role": "condition"}], "elements": [{"span": "s1", "atoms": [], "derived": ["drv.motion.parked"], "justification": "'Park' applies DEF-NRS-484A-155: 'the standing of a vehicle, whether occupied or not, otherwise than temporarily for the purpose of and while actually engaged in loading or unloading of merchandise or passengers'. drv.motion.parked denotes 'the standing of a vehicle, whether occupied or not, observed as a at rest at every observation of the window behind the observation, of length min_duration'; 'A halt shorter than min_duration, which may be the temporary halt the definition leaves out, is not denoted', which carries the definition's exclusion of a temporary halt for loading. Same mapping as the index's 'It shall be unlawful for any person to park' (LVMC_11_40_170)."}, {"span": "s2", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is admitted as the aggregate DEF-NRS-484A-320::vehicle; ru.aggregate is 'membership of a legal aggregate'. It is not a relational role (who drives) and no class atom replaces an admitted aggregate."}, {"span": "s3", "atoms": ["st.parking_space", "rel.occupies"], "derived": [], "justification": "'Access aisle' applies DEF-LVMC-11-02-030: an area 'Adjacent to a parking space designated for the handicapped' and 'Marked by spaced, crosshatched or diagonal stripes'. st.parking_space is a 'marked bay for standing or parking; designation in {general, disabled, disabled_side_lift, access_aisle, municipal, charging}': the designation access_aisle is the marked aisle beside a disabled bay. 'in' places the vehicle there: rel.occupies, 'a road user's footprint overlaps a lane / region', anchors the vehicle to the aisle it is in, not to any aisle of the scene."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "The subject is a vehicle (ru.aggregate DEF-NRS-484A-320::vehicle) and its footprint overlaps a parking-space region whose designation is access_aisle (st.parking_space, rel.occupies) at the observation.", "obligation": "The subject is not parked (drv.motion.parked with speed_tol p.halt_speed_tolerance and min_duration p.parking_min_duration) while its footprint overlaps that access-aisle region: for every parking-space region of designation access_aisle the subject occupies at the observation, the subject is not parked there.", "params": ["p.halt_speed_tolerance", "p.parking_min_duration"], "narrowings": [{"span": "s1", "why": "'No person shall park' is read through the vehicle's own standing; whoever or whatever controls it, the duty binds the vehicle's conduct.", "kind": "observable_reading", "category": "agency"}, {"span": "s1", "why": "The definition's exclusion of a halt made 'temporarily for the purpose of and while actually engaged in loading or unloading' is read through the halt's duration: a halt shorter than p.parking_min_duration is the temporary halt and is not parking; the loading purpose itself is not observed.", "kind": "observable_reading", "category": "purpose"}, {"span": "s3", "why": "The defined area's design for 'unobstructed ingress, egress and access' and its adjacency to a disabled bay are read through the mapped marking: a parking-space region the source designates access_aisle is the access aisle.", "kind": "observable_reading", "category": "status"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A passenger car (vehicle aggregate) comes to rest with its footprint overlapping a st.parking_space of designation access_aisle beside a disabled bay and stays at rest there (kin.speed at or below the tolerance) for longer than p.parking_min_duration."}, {"name": "permit", "expected": "compliant", "narrative": "A passenger car halts briefly in an access-aisle parking space, shorter than p.parking_min_duration, to let a passenger out, then drives off; drv.motion.parked never holds while it occupies the aisle."}, {"name": "idle", "expected": "not_applicable", "narrative": "A passenger car parks for a long time in a parking space of designation general; its footprint never overlaps an access_aisle region."}, {"name": "blind", "expected": "unknown", "masked": ["rel.occupies"], "narrative": "A passenger car stands at rest next to an access-aisle region for longer than p.parking_min_duration; the source does not observe rel.occupies, so whether it is in the aisle is unknown."}], "literals": [], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source's kinematic channel"}, {"name": "p.parking_min_duration", "unit": "s", "value": 180.0, "convention": "the longest halt counted as temporary, as for loading or unloading: a common time limit of a passenger loading zone", "source": "municipal curbside management practice: passenger loading zone time limits"}], "gaps": [], "gap_resolutions": []}
{"node_id": "LVMC_11_52_180_C", "law_refs": ["LVMC-11-52-180-C"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "A vehicle", "role": "subject"}, {"id": "s2", "text": "otherwise lawfully", "role": "condition"}, {"id": "s3", "text": "parked in an alley", "role": "condition"}, {"id": "s4", "text": "shall not park for a greater period than thirty minutes within any one-hour period.", "role": "obligation"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is admitted as DEF-NRS-484A-320::vehicle; ru.aggregate is 'membership of a legal aggregate', never a relational role or a class list."}, {"span": "s3", "atoms": ["rel.occupies", "st.alley"], "derived": ["drv.motion.parked"], "justification": "'parked' applies DEF-NRS-484A-155 'the standing of a vehicle, whether occupied or not, otherwise than temporarily ...', carried by drv.motion.parked ('at rest at every observation of the window behind ... of length min_duration'; a shorter halt 'is not denoted'). 'Alley' applies DEF-NRS-484A-015 'a highway ... Within a city block ... Which primarily services access to the rear entrance of abutting property'; st.alley is 'a narrow way within a block serving the rear of properties'. rel.occupies ('a road user's footprint overlaps a lane / region', whose list names the alley) anchors the vehicle to the alley it is parked in."}, {"span": "s4", "atoms": ["kin.time", "rel.occupies", "st.alley"], "derived": ["drv.motion.parked"], "justification": "Nearest carriers only (the span carries an operator gap): the obligation limits the total time the vehicle is parked (drv.motion.parked) in the alley (rel.occupies, st.alley) within any one-hour window behind the observation, measured on kin.time ('instant of observation of a scene'). holdsFor measures only one continuous run and Term.sinceRise only the latest run, so neither sums several parked periods within the hour; the cumulative duration is not written by any operator."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [{"span": "s2", "why": "'otherwise lawfully' states that a vehicle whose parking complies with every other rule is still held to the thirty-minute limit; it does not exempt a vehicle parked unlawfully in another respect, which is no less held to the limit. The duty is the same whether or not the vehicle's parking otherwise complies.", "scope": "none"}], "binders": [{"name": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "The subject is a vehicle and is parked (drv.motion.parked with p.halt_speed_tolerance, p.parking_min_duration) with its footprint overlapping an alley region (st.alley, rel.occupies) at the observation.", "obligation": "Within the one-hour window behind the observation, the total time during which the subject was parked in that alley is not greater than thirty minutes (the literals of span s4). The cumulative duration over several parked periods is the operator gap of span s4.", "params": ["p.halt_speed_tolerance", "p.parking_min_duration"], "narrowings": [{"span": "s4", "why": "The definition's exclusion of a temporary halt for loading or unloading is read through the halt's duration (drv.motion.parked's min_duration); the loading purpose is not observed.", "kind": "observable_reading", "category": "purpose"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A passenger car comes to rest in an alley (rel.occupies st.alley) and stays at rest there for forty minutes."}, {"name": "permit", "expected": "compliant", "narrative": "A passenger car parks in an alley for ten minutes and then drives out of the alley; it does not return within the hour."}, {"name": "idle", "expected": "not_applicable", "narrative": "A passenger car parks for an hour on a street (st.highway) that is not an alley; its footprint never overlaps an st.alley region."}, {"name": "blind", "expected": "unknown", "masked": ["rel.occupies"], "narrative": "A passenger car stands at rest for forty minutes at the mouth of an alley; the source does not observe rel.occupies, so whether it is in the alley is unknown."}, {"name": "branch_1", "expected": "violated", "narrative": "A passenger car parks in an alley for twenty minutes, drives out for five minutes, and returns to park in the same alley for another twenty minutes: forty minutes parked within one hour."}], "literals": [{"span": "s4", "text": "thirty minutes", "value": 30, "unit": "min"}, {"span": "s4", "text": "one-hour", "value": 1, "unit": "h"}], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source's kinematic channel"}, {"name": "p.parking_min_duration", "unit": "s", "value": 180.0, "convention": "the longest halt counted as temporary, as for loading or unloading: a common time limit of a passenger loading zone", "source": "municipal curbside management practice: passenger loading zone time limits"}], "gaps": [{"span": "s4", "kind": "operator", "proposal": "durationWithin (m : Measure) (d : Term) (subject : String) (φ : Formula) : Term -- the total time, within the window of length d behind the observation, during which φ held (each interval between consecutive observations counted where φ held at both its ends), unknown where the window is truncated or φ is unknown on a part that could change the comparison. It decides the action the law forbids: a vehicle parked in an alley for more than the stated time in total within any one-hour period, over several parked periods; holdsFor and sinceRise measure one continuous run only, so a vehicle that leaves briefly and returns escapes them.", "nearest": ["holdsFor", "Term.sinceRise", "count", "kin.time"]}], "gap_resolutions": []}
{"node_id": "LVMC_11_52_300", "law_refs": ["LVMC-11-52-300"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "Except for a motor vehicle,", "role": "exception"}, {"id": "s2", "text": "no person shall park", "role": "obligation"}, {"id": "s3", "text": "any vehicle", "role": "subject"}, {"id": "s4", "text": "on any street", "role": "condition"}, {"id": "s5", "text": "for a period of time longer than thirty minutes", "role": "condition"}, {"id": "s6", "text": "between the hours of one a.m. and six a.m. of any day.", "role": "condition"}], "elements": [{"span": "s1", "atoms": ["ru.aggregate=DEF-NRS-484A-130::motor_vehicle"], "derived": [], "justification": "'motor vehicle' is admitted as DEF-NRS-484A-130::motor_vehicle ('every vehicle which is self-propelled but not operated upon rails'); ru.aggregate is 'membership of a legal aggregate'. The class atom ru.motor_vehicle never replaces an admitted aggregate."}, {"span": "s2", "atoms": [], "derived": ["drv.motion.parked"], "justification": "'park' applies DEF-NRS-484A-155 'the standing of a vehicle, whether occupied or not, otherwise than temporarily for the purpose of and while actually engaged in loading or unloading'; drv.motion.parked denotes 'at rest at every observation of the window behind the observation, of length min_duration', a shorter halt 'is not denoted'. Same mapping as the index's 'It shall be unlawful for any person to park'."}, {"span": "s3", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is admitted as DEF-NRS-484A-320::vehicle; ru.aggregate is 'membership of a legal aggregate'."}, {"span": "s4", "atoms": ["rel.occupies", "st.highway"], "derived": [], "justification": "'Street' applies DEF-NRS-484A-265 'the entire width between the boundary lines of every highway inside the territorial limits of a city'; st.highway is 'the entire public way between its boundary lines, including sidewalks and shoulders' (not the roadway alone, whose exclusion does not apply since the definition takes the entire width). rel.occupies anchors the vehicle's footprint on it. Same mapping as the index's 'upon any street' (LVMC_11_48_050); the city limits are the jurisdiction this city ordinance applies in."}, {"span": "s5", "atoms": ["kin.time"], "derived": ["drv.motion.parked"], "justification": "'for a period of time longer than thirty minutes' is one continuous period of parking, a time window behind the observation of the stated length at every observation of which the vehicle was parked on the street within the hours; the window reads kin.time, 'instant of observation of a scene'."}, {"span": "s6", "atoms": ["env.civil_time"], "derived": [], "justification": "env.civil_time is 'the local calendar time of the observation: date, weekday, time of day (from the recording's metadata, not from the scene)'; the law states the hours itself, so the time of day is compared with the stated one a.m. and six a.m. 'Not a stand-in for: kin.time' does not apply: the clock of day, not the order of observations, is read. Same mapping as the index's 'between the hours of seven p.m. and six a.m.;' (LVMC_11_48_050)."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "The subject is a vehicle and not a motor vehicle (ru.aggregate DEF-NRS-484A-130::motor_vehicle does not hold), its footprint overlaps a street (st.highway, rel.occupies), and the civil time of day (env.civil_time) is at or after one a.m. and before six a.m.", "obligation": "It is not the case that, at every observation of the time window of thirty minutes behind the observation, the subject was parked (drv.motion.parked with p.halt_speed_tolerance, p.parking_min_duration) with its footprint on a street and with the civil time of day at or after one a.m. and before six a.m.", "params": ["p.halt_speed_tolerance", "p.parking_min_duration"], "narrowings": [{"span": "s2", "why": "'no person shall park' is read through the vehicle's own standing, whoever controls it; the definition's temporary halt for loading or unloading is read through the halt's duration (min_duration), the purpose itself not being observed.", "kind": "observable_reading", "category": "purpose"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A trailer (vehicle aggregate, not a motor vehicle) stands at rest on a street from 01:10 to 01:50 civil time."}, {"name": "permit", "expected": "compliant", "narrative": "A trailer stands at rest on a street from 02:00 to 02:20 civil time and is then towed away."}, {"name": "idle", "expected": "not_applicable", "narrative": "A passenger car (motor vehicle aggregate) stands at rest on a street from 01:00 to 05:00 civil time."}, {"name": "blind", "expected": "unknown", "masked": ["env.civil_time"], "narrative": "A trailer stands at rest on a street for forty minutes; the recording carries no civil time, so whether the period lies between one and six a.m. is unknown."}, {"name": "branch_1", "expected": "compliant", "narrative": "A trailer stands at rest on a street from 00:30 to 01:20 civil time and is then towed away: only twenty minutes of the period lie within the hours."}], "literals": [{"span": "s5", "text": "thirty minutes", "value": 30, "unit": "min"}, {"span": "s6", "text": "one a.m.", "value": 1, "unit": "h"}, {"span": "s6", "text": "six a.m.", "value": 6, "unit": "h"}], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source's kinematic channel"}, {"name": "p.parking_min_duration", "unit": "s", "value": 180.0, "convention": "the longest halt counted as temporary, as for loading or unloading: a common time limit of a passenger loading zone", "source": "municipal curbside management practice: passenger loading zone time limits"}], "gaps": [], "gap_resolutions": []}
{"node_id": "LVMC_11_52_305_A", "law_refs": ["LVMC-11-52-305-A"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-LVMC-11-02-070::commercial_vehicle", "ru.aggregate=DEF-LVMC-11-02-110::recreational_vehicle", "ru.aggregate=DEF-LVMC-11-02-170::trailer", "ru.aggregate=DEF-NRS-484A-320::vehicle", "ru.trailer_or_combination"]}, "segmentation": [{"id": "a1", "text": "Except as otherwise provided in this Section", "role": "exception"}, {"id": "a2", "text": "or as permitted by posted sign,", "role": "exception"}, {"id": "a3", "text": "it is unlawful for a person to stand, park or store,", "role": "obligation"}, {"id": "a4", "text": "upon any street", "role": "condition"}, {"id": "a5", "text": "adjacent to a residence district, public school or public park,", "role": "condition"}, {"id": "a6", "text": "a commercial vehicle, recreational vehicle, trailer,", "role": "subject"}, {"id": "a7", "text": "or any combination of vehicle and trailer", "role": "subject"}, {"id": "a8", "text": "having an overall length of twenty-four feet or more", "role": "condition"}, {"id": "a9", "text": "or an unladen weight in excess of eight thousand pounds.", "role": "condition"}, {"id": "a10", "text": "For purposes of the preceding sentence, a \"residence district\" means the territory contiguous to a street, not comprising a business district, in which the parcels abutting such street for a distance of three hundred feet or more are mainly occupied by dwellings or by dwellings and buildings in use for residence.", "role": "definitional"}, {"id": "a11", "text": "The provisions of Subsection (A) do not apply to a commercial vehicle that is:", "role": "exception"}, {"id": "a12", "text": "(1) Parked in front of property from which or to which goods or passengers are being picked up or delivered,", "role": "exception"}, {"id": "a13", "text": "but only for that period of time during which goods or passengers are being expeditiously loaded or unloaded;", "role": "standard"}, {"id": "a14", "text": "or (2) Being used in conjunction with the performance of service, repair, construction or similar essential use within the immediate neighborhood.", "role": "exception"}], "elements": [{"span": "a2", "atoms": ["dev.regulatory_sign", "dev.zone_sign", "dev.governs"], "derived": [], "justification": "Nearest carriers only (atom gap): dev.regulatory_sign's codes (no_stopping, no_standing, no_parking, angle_parking, ...) prohibit or regulate and none permits the standing or parking of a vehicle class; dev.zone_sign kind parking_restricted with its conditions states where a restriction applies, and a condition that holds there makes the restriction apply rather than permitting the vehicle; dev.governs ties a device to the region it controls. None carries a posted permission."}, {"span": "a3", "atoms": [], "derived": ["drv.motion.parked"], "justification": "'stand' applies DEF-NRS-484A-250 'the halting of a vehicle, whether occupied or not, otherwise than for the purpose of and while actually engaged in receiving or discharging passengers'; 'park' DEF-NRS-484A-155; 'store' is a longer standing still. Standing contains parking and storing, so the three are one prohibition of standing: drv.motion.parked ('at rest at every observation of the window behind ... of length min_duration') with the standing window p.standing_min_duration, as the index maps 'No person shall stand or park a vehicle' (LVMC_11_52_040_A)."}, {"span": "a4", "atoms": ["rel.occupies", "st.highway"], "derived": [], "justification": "'Street' applies DEF-NRS-484A-265 'the entire width between the boundary lines of every highway inside the territorial limits of a city'; st.highway is 'the entire public way between its boundary lines, including sidewalks and shoulders', not the roadway alone. rel.occupies anchors the vehicle on it. Same mapping as the index's 'upon any street'."}, {"span": "a6", "atoms": ["ru.aggregate=DEF-LVMC-11-02-070::commercial_vehicle", "ru.aggregate=DEF-LVMC-11-02-110::recreational_vehicle", "ru.aggregate=DEF-LVMC-11-02-170::trailer"], "derived": [], "justification": "Each word is an admitted aggregate: 'commercial vehicle' DEF-LVMC-11-02-070::commercial_vehicle, 'recreational vehicle' DEF-LVMC-11-02-110::recreational_vehicle, 'trailer' DEF-LVMC-11-02-170::trailer; ru.aggregate is 'membership of a legal aggregate', never expanded into classes."}, {"span": "a7", "atoms": ["ru.trailer_or_combination", "ru.aggregate=DEF-NRS-484A-320::vehicle", "ru.aggregate=DEF-LVMC-11-02-170::trailer"], "derived": [], "justification": "'combination of vehicle and trailer' is no defined term; ru.trailer_or_combination is 'vehicle drawn by another, or the combination', which denotes the combination as one road user. Its members are a 'vehicle' (admitted DEF-NRS-484A-320::vehicle) and a 'trailer' (admitted DEF-LVMC-11-02-170::trailer), each claimed as its aggregate."}, {"span": "a8", "atoms": ["kin.extent"], "derived": [], "justification": "kin.extent is 'the body's size along its axes about the reference point ... a formula reads the full length, width and height'; the overall length is its length, compared with the stated twenty-four feet."}, {"span": "a9", "atoms": ["ru.commercial_motor_vehicle", "kin.extent"], "derived": [], "justification": "Nearest carriers only (atom gap): ru.commercial_motor_vehicle is a 'vehicle over the jurisdiction's commercial mass class or marked as commercially licensed', a class threshold the jurisdiction sets, not the stated unladen weight of eight thousand pounds; kin.extent is the body's size, not its mass. No atom carries a vehicle's unladen weight."}, {"span": "a11", "atoms": ["ru.aggregate=DEF-LVMC-11-02-070::commercial_vehicle"], "derived": [], "justification": "'commercial vehicle' is admitted as DEF-LVMC-11-02-070::commercial_vehicle ('a motor vehicle or combination of motor vehicle and trailer maintained or used primarily for the furtherance of a commercial enterprise'); the exceptions (1) and (2) are read only for a subject that is one."}, {"span": "a12", "atoms": ["sig.door_open"], "derived": ["drv.motion.complete_halt"], "justification": "Goods or passengers being picked up or delivered is a purpose, read by the conduct it explains: the commercial vehicle is at rest (drv.motion.complete_halt, 'at rest at the observation ... complete cessation from movement') with a door open (sig.door_open, 'a door open; side in {traffic, curb}') through which goods or passengers pass. 'In front of property' is any frontage the street serves and restricts nothing beyond the vehicle standing on the street."}, {"span": "a14", "atoms": ["ru.official_vehicle", "dev.temporary_traffic_control"], "derived": [], "justification": "Nearest carriers only (atom gap): ru.official_vehicle is 'a vehicle in official or contracted road service', a livery class, not a vehicle's use at a nearby job ('Not a stand-in for: an emergency vehicle' aside, it does not say what the vehicle is used for now); dev.temporary_traffic_control marks 'works, a closure or an obstruction' on the road, not service, repair or construction at a property in the neighborhood. No atom carries a vehicle's present use for such work."}], "operationalizations": [{"span": "a13", "standard": "expeditiously loaded or unloaded", "concepts": ["drv.motion.complete_halt", "kin.time"], "params": ["p.commercial_loading_max_halt", "p.halt_speed_tolerance"], "convention": "the excepted period is the current halt (drv.motion.complete_halt with p.halt_speed_tolerance) measured from its onset (time since the halt last became true, on kin.time) up to p.commercial_loading_max_halt, the thirty-minute limit common to commercial loading zones: a halt longer than that is not expeditious loading", "surrogate": false}], "assumptions": [{"span": "a5", "id": "asm.street_adjacent_to_residence_school_or_park", "meaning": "the street the road user is on at the observation is adjacent to a residence district, to the grounds of a public school or to a public park, as the map's reading classifies the street's frontage"}], "intentions": [], "compositions": [], "residues": [{"span": "a1", "why": "The provisions of this Section that provide otherwise are its subsection (B), whose exceptions (1) and (2) are spans a11 to a14 of this same line, carried by this node; the words add no exception beyond them, so the duty is the same whether or not they are read.", "scope": "none"}], "binders": [{"name": "subject", "class_elements": ["ru.aggregate=DEF-LVMC-11-02-070::commercial_vehicle", "ru.aggregate=DEF-LVMC-11-02-110::recreational_vehicle", "ru.aggregate=DEF-LVMC-11-02-170::trailer", "ru.aggregate=DEF-NRS-484A-320::vehicle", "ru.trailer_or_combination"]}], "applicability": "The subject is a commercial vehicle, a recreational vehicle, a trailer, or a vehicle that is a vehicle-and-trailer combination (ru.trailer_or_combination); its overall length (kin.extent length) is at least twenty-four feet or its unladen weight exceeds eight thousand pounds (atom gap of span a9); its footprint is on a street (st.highway, rel.occupies); the assumption asm.street_adjacent_to_residence_school_or_park holds; no posted sign permits its standing there (atom gap of span a2); and it is not a commercial vehicle excepted by (1) — at rest with a door open in a halt that has lasted no longer than p.commercial_loading_max_halt — or by (2) — in use for nearby service, repair or construction work (atom gap of span a14).", "obligation": "The subject is not standing (drv.motion.parked with p.halt_speed_tolerance and min_duration p.standing_min_duration) on that street.", "params": ["p.halt_speed_tolerance", "p.standing_min_duration", "p.commercial_loading_max_halt"], "narrowings": [{"span": "a3", "why": "'it is unlawful for a person to stand, park or store' is read through the vehicle's own standing, whoever controls it; the definitions' exclusion of a halt for receiving or discharging passengers or loading is read through the halt's duration (p.standing_min_duration), the purpose not being observed.", "kind": "observable_reading", "category": "purpose"}, {"span": "a12", "why": "Goods or passengers being picked up or delivered is read through the commercial vehicle at rest with a door open; the purpose itself is not observed.", "kind": "observable_reading", "category": "purpose"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A trailer (trailer aggregate) with a kin.extent length of ten metres stands at rest for ten minutes on a street for which asm.street_adjacent_to_residence_school_or_park is declared; no sign is posted."}, {"name": "permit", "expected": "compliant", "narrative": "A recreational vehicle with a kin.extent length of ten metres drives along a street adjacent to a residence district and halts for twenty seconds at a signal, then continues; it never stands for p.standing_min_duration."}, {"name": "idle", "expected": "not_applicable", "narrative": "A trailer with a kin.extent length of ten metres stands at rest for an hour on a street for which the assumption asm.street_adjacent_to_residence_school_or_park is declared false."}, {"name": "blind", "expected": "unknown", "masked": ["rel.occupies"], "narrative": "A trailer ten metres long stands at rest for ten minutes beside a street adjacent to a residence district; the source does not observe rel.occupies, so whether it stands on the street is unknown."}, {"name": "branch_1", "expected": "compliant", "narrative": "A commercial vehicle ten metres long stands at rest on a street adjacent to a residence district with a door open (sig.door_open) for ten minutes, then drives off: exception (1) within the expeditious-loading bound."}], "literals": [{"span": "a8", "text": "twenty-four feet", "value": 24, "unit": "ft"}], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source's kinematic channel"}, {"name": "p.standing_min_duration", "unit": "s", "value": 60.0, "convention": "the longest halt counted as receiving or discharging passengers or loading rather than standing: a passenger pick-up dwell at the curb", "source": "curbside passenger pick-up dwell times in curb management studies"}, {"name": "p.commercial_loading_max_halt", "unit": "s", "value": 1800.0, "convention": "the longest halt of a commercial vehicle counted as expeditious loading or unloading of goods or passengers: the thirty-minute limit common to commercial loading zones", "source": "municipal commercial loading zone time limits"}], "gaps": [{"span": "a2", "kind": "atom", "proposal": "`dev.parking_permission_sign` | a posted sign permitting the standing, parking or storage of a vehicle class at the place it governs, with the same structured **conditions** attribute as `dev.zone_sign` (hours, days, duration, class) **Not a stand-in for:** a restriction sign (`dev.regulatory_sign` no_parking or no_standing, `dev.zone_sign` parking_restricted) — a permission excuses where a restriction forbids | general. It decides where the law permits the standing it otherwise forbids.", "nearest": ["dev.regulatory_sign", "dev.zone_sign"]}, {"span": "a9", "kind": "atom", "proposal": "`ru.unladen_mass` | the mass of a vehicle without load, as registered or measured (kg); for a combination, the sum of its units **Not a stand-in for:** the body's size (`kin.extent`) or a commercial class (`ru.commercial_motor_vehicle`) | general. It decides which road users the duty concerns: a vehicle shorter than the stated length but heavier than the stated weight.", "nearest": ["ru.commercial_motor_vehicle", "kin.extent"]}, {"span": "a14", "kind": "atom", "proposal": "`ru.work_service_use` | the vehicle is in use for service, repair, construction or similar work at a site near where it stands, as the source records its assignment or observes its work equipment deployed or its crew at work beside it **Not a stand-in for:** a vehicle in official road service (`ru.official_vehicle`) or works on the road (`dev.temporary_traffic_control`) | general. It decides which commercial vehicles the duty excuses.", "nearest": ["ru.official_vehicle", "dev.temporary_traffic_control"]}], "gap_resolutions": []}
{"node_id": "LVMC_11_52_340", "law_refs": ["LVMC-11-52-340"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}, "segmentation": [{"id": "s1", "text": "The City Council may designate parking spaces upon City streets or in City parking facilities for the parking of City vehicles.", "role": "condition"}, {"id": "s2", "text": "It is unlawful to park", "role": "obligation"}, {"id": "s3", "text": "a vehicle", "role": "subject"}, {"id": "s4", "text": "other than a City vehicle", "role": "exception"}, {"id": "s5", "text": "in any such space that has been duly posted or marked.", "role": "condition"}], "elements": [{"span": "s1", "atoms": ["st.parking_space"], "derived": [], "justification": "The designated space is the referent of 'such space' in s5. st.parking_space is a 'marked bay for standing or parking; ... designation in {general, disabled, disabled_side_lift, access_aisle, municipal, charging}': designation municipal is a bay reserved for the city's own vehicles, whether on a street or in a city parking facility (DEF-LVMC-11-02-050: a lot or garage 'which the City owns, operates or maintains'); the place of the bay restricts nothing beyond its municipal designation, which the Council makes only there."}, {"span": "s2", "atoms": [], "derived": ["drv.motion.parked"], "justification": "'park' applies DEF-NRS-484A-155 'the standing of a vehicle, whether occupied or not, otherwise than temporarily for the purpose of and while actually engaged in loading or unloading'; drv.motion.parked denotes 'at rest at every observation of the window behind ... of length min_duration', a shorter halt 'is not denoted'. Same mapping as the index's 'It shall be unlawful for any person to park'."}, {"span": "s3", "atoms": ["ru.aggregate=DEF-NRS-484A-320::vehicle"], "derived": [], "justification": "'vehicle' is admitted as DEF-NRS-484A-320::vehicle; ru.aggregate is 'membership of a legal aggregate'."}, {"span": "s4", "atoms": ["ru.official_vehicle"], "derived": [], "justification": "A City vehicle is one the incorporated city (DEF-NRS-484A-045) operates; ru.official_vehicle is 'a vehicle in official or contracted road service, identifiable by livery or equipment; kind in {..., municipal, ...}', and kind municipal is the city's own vehicle. 'Not a stand-in for: an emergency vehicle' is respected: the exception reads the municipal kind, not the emergency class."}, {"span": "s5", "atoms": ["st.parking_space", "rel.occupies"], "derived": [], "justification": "'such space' is the space s1 designates: a st.parking_space of designation municipal; 'duly posted or marked' is its posting or marking, whose presence on the road is the evidence of the designation. rel.occupies ('a road user's footprint overlaps a lane / region') anchors the vehicle in that space, not any municipal space of the scene."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "The subject is a vehicle that is not a municipal official vehicle (ru.official_vehicle kind municipal does not hold), and its footprint overlaps a parking-space region of designation municipal (st.parking_space, rel.occupies) at the observation.", "obligation": "For every parking-space region of designation municipal the subject occupies at the observation, the subject is not parked there (drv.motion.parked with p.halt_speed_tolerance, p.parking_min_duration).", "params": ["p.halt_speed_tolerance", "p.parking_min_duration"], "narrowings": [{"span": "s5", "why": "That the space was designated by the City Council and 'duly posted or marked' is read through the mapped municipal designation of the bay, the posting or marking on the road being the evidence of the designation.", "kind": "observable_reading", "category": "status"}, {"span": "s2", "why": "The definition's temporary halt for loading or unloading is read through the halt's duration (min_duration p.parking_min_duration); the loading purpose is not observed.", "kind": "observable_reading", "category": "purpose"}, {"span": "s2", "why": "A City vehicle is recognized by its municipal livery or equipment (ru.official_vehicle kind municipal); a city-owned vehicle without such livery, or a city emergency vehicle the source labels only by its emergency class, is read as not a City vehicle, so the duty is applied to it.", "kind": "reading"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A private passenger car (vehicle aggregate, not ru.official_vehicle municipal) comes to rest in a st.parking_space of designation municipal and stays at rest there for ten minutes."}, {"name": "permit", "expected": "compliant", "narrative": "A private passenger car halts for thirty seconds in a municipal parking space to let a passenger out and then drives off; it is never parked there."}, {"name": "idle", "expected": "not_applicable", "narrative": "A ru.official_vehicle of kind municipal stays at rest for an hour in a municipal parking space."}, {"name": "blind", "expected": "unknown", "masked": ["rel.occupies"], "narrative": "A private passenger car stands at rest for ten minutes beside a municipal parking space; the source does not observe rel.occupies, so whether it is in the space is unknown."}, {"name": "branch_1", "expected": "not_applicable", "narrative": "A private passenger car stays at rest for an hour in a parking space of designation general; it occupies no municipal space."}], "literals": [], "param_proposals": [{"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source's kinematic channel"}, {"name": "p.parking_min_duration", "unit": "s", "value": 180.0, "convention": "the longest halt counted as temporary, as for loading or unloading: a common time limit of a passenger loading zone", "source": "municipal curbside management practice: passenger loading zone time limits"}], "gaps": [], "gap_resolutions": []}
